begin;
set local storage.allow_delete_query=true;
create temp table ids(name text primary key,id uuid default gen_random_uuid());
insert into ids(name) values('owner'),('viewer'),('other'),('company'),('elsewhere'),('batch'),('batch2');
grant select on ids to authenticated,service_role;
create function pg_temp.id(text) returns uuid language sql as $$select id from ids where name=$1$$;
create temp table results(name text,passed boolean);
grant insert,select on results to authenticated,service_role;
create function pg_temp.ok(name text,passed boolean) returns void language plpgsql as $$begin
 if passed is distinct from true then raise exception 'FAILED: %',name;end if;insert into results values(name,true);end$$;
create function pg_temp.denied(name text,statement text) returns void language plpgsql as $$begin
 begin execute statement;exception when others then insert into results values(name,true);return;end;
 raise exception 'FAILED unexpectedly allowed: %',name;end$$;
insert into auth.users(id,email,email_confirmed_at,role,aud) select id,id::text||'@resume-test.invalid',now(),'authenticated','authenticated' from ids where name in ('owner','viewer','other');
insert into public.companies(id,name) values(pg_temp.id('company'),'Resume Test'),(pg_temp.id('elsewhere'),'Other company');
insert into public.company_members values(pg_temp.id('company'),pg_temp.id('owner'),'owner',now()),(pg_temp.id('company'),pg_temp.id('viewer'),'viewer',now()),(pg_temp.id('elsewhere'),pg_temp.id('other'),'owner',now());
insert into public.resume_batches(id,company_id,uploaded_by,source,file_count) values
 (pg_temp.id('batch'),pg_temp.id('company'),pg_temp.id('owner'),'email',5),
 (pg_temp.id('batch2'),pg_temp.id('company'),pg_temp.id('owner'),'email',5);
select set_config('request.jwt.claims',json_build_object('sub',pg_temp.id('owner'),'role','authenticated')::text,true);
set local role authenticated;
select pg_temp.denied('batch size enforced in database',$q$select public.begin_resume_batch(pg_temp.id('company'),6,'email')$q$);
select pg_temp.denied('candidate cannot bypass validated intake',$q$insert into public.candidates(company_id,nome) values(pg_temp.id('company'),'bypass')$q$);
select pg_temp.denied('client cannot reserve trusted hash',$q$select public.reserve_resume(pg_temp.id('owner'),pg_temp.id('company'),pg_temp.id('batch'),0,repeat('a',64),'a.pdf','application/pdf',10,1)$q$);
select pg_temp.denied('client cannot forge document',$q$insert into public.resume_documents(company_id,candidate_id,sha256,filename,mime_type,byte_size,page_count,source) values(pg_temp.id('company'),gen_random_uuid(),repeat('a',64),'a.pdf','application/pdf',10,1,'email')$q$);
reset role;
set local role service_role;
select pg_temp.denied('viewer cannot reserve',$q$select public.reserve_resume(pg_temp.id('viewer'),pg_temp.id('company'),pg_temp.id('batch'),0,repeat('a',64),'a.pdf','application/pdf',10,1)$q$);
select pg_temp.denied('cross-company batch rejected',$q$select public.reserve_resume(pg_temp.id('other'),pg_temp.id('elsewhere'),pg_temp.id('batch'),0,repeat('a',64),'a.pdf','application/pdf',10,1)$q$);
select pg_temp.denied('slot quota enforced',$q$select public.reserve_resume(pg_temp.id('owner'),pg_temp.id('company'),pg_temp.id('batch'),5,repeat('a',64),'a.pdf','application/pdf',10,1)$q$);
select pg_temp.denied('oversized trusted record rolled back',$q$select public.reserve_resume(pg_temp.id('owner'),pg_temp.id('company'),pg_temp.id('batch'),0,repeat('a',64),'a.pdf','application/pdf',10485761,1)$q$);
select pg_temp.denied('page quota enforced',$q$select public.reserve_resume(pg_temp.id('owner'),pg_temp.id('company'),pg_temp.id('batch'),0,repeat('a',64),'a.pdf','application/pdf',10,21)$q$);
select pg_temp.ok('failed registration leaves no candidates',(select count(*)=0 from public.candidates where company_id=pg_temp.id('company')));
select set_config('test.reservation',public.reserve_resume(pg_temp.id('owner'),pg_temp.id('company'),pg_temp.id('batch'),0,repeat('a',64),'a.pdf','application/pdf',10,1)::text,true);
select pg_temp.ok('first request owns upload',(current_setting('test.reservation')::jsonb->>'owned')::boolean);
select pg_temp.ok('candidate and document created together',(select count(*)=1 from public.resume_documents d join public.candidates c on c.id=d.candidate_id where d.company_id=pg_temp.id('company')));
select pg_temp.ok('actor timestamp and origin recorded',(select uploaded_by=pg_temp.id('owner') and source='email' and created_at is not null from public.resume_documents where company_id=pg_temp.id('company')));
select pg_temp.ok('repeat request does not own upload',not(public.reserve_resume(pg_temp.id('owner'),pg_temp.id('company'),pg_temp.id('batch'),0,repeat('a',64),'a.pdf','application/pdf',10,1)->>'owned')::boolean);
select pg_temp.ok('new batch same bytes reuses candidate',public.reserve_resume(pg_temp.id('owner'),pg_temp.id('company'),pg_temp.id('batch2'),0,repeat('a',64),'renamed.pdf','application/pdf',10,1)->>'candidateId'=current_setting('test.reservation')::jsonb->>'candidateId');
select pg_temp.denied('slot cannot be overwritten',$q$select public.reserve_resume(pg_temp.id('owner'),pg_temp.id('company'),pg_temp.id('batch'),0,repeat('b',64),'b.pdf','application/pdf',10,1)$q$);
select pg_temp.denied('wrong completion token rejected',$q$select public.finish_resume_upload(pg_temp.id('owner'),pg_temp.id('company'),(current_setting('test.reservation')::jsonb->>'documentId')::uuid,gen_random_uuid())$q$);
select public.finish_resume_upload(pg_temp.id('owner'),pg_temp.id('company'),(current_setting('test.reservation')::jsonb->>'documentId')::uuid,(current_setting('test.reservation')::jsonb->>'token')::uuid);
select set_config('test.claim',public.claim_resume_extraction(pg_temp.id('owner'),pg_temp.id('company'),(current_setting('test.reservation')::jsonb->>'candidateId')::uuid)::text,true);
select pg_temp.ok('first extraction owns one-use claim',(current_setting('test.claim')::jsonb->>'owned')::boolean);
select pg_temp.ok('simultaneous extraction rejected',not(public.claim_resume_extraction(pg_temp.id('owner'),pg_temp.id('company'),(current_setting('test.reservation')::jsonb->>'candidateId')::uuid)->>'owned')::boolean);
select public.finish_resume_extraction(pg_temp.id('owner'),pg_temp.id('company'),(current_setting('test.reservation')::jsonb->>'candidateId')::uuid,(current_setting('test.claim')::jsonb->>'token')::uuid,'{}','erro','Synthetic failure');
select pg_temp.ok('ambiguous AI failure never recharged',not(public.claim_resume_extraction(pg_temp.id('owner'),pg_temp.id('company'),(current_setting('test.reservation')::jsonb->>'candidateId')::uuid)->>'owned')::boolean);
reset role;
select set_config('request.jwt.claims',json_build_object('sub',pg_temp.id('other'),'role','authenticated')::text,true);
set local role authenticated;
select pg_temp.ok('documents hidden from other company',(select count(*)=0 from public.resume_documents));
select pg_temp.ok('batches hidden from other company',(select count(*)=0 from public.resume_batches));
select pg_temp.denied('client cannot change provenance','update public.resume_documents set source=''outro''');
reset role;
set local role service_role;
select set_config('test.interrupted',public.reserve_resume(pg_temp.id('owner'),pg_temp.id('company'),pg_temp.id('batch'),1,repeat('c',64),'interrupted.pdf','application/pdf',10,1)::text,true);
select pg_temp.ok('recent upload not cleaned',(select count(*)=0 from public.claim_resume_cleanup(pg_temp.id('owner'),pg_temp.id('company'))));
update public.resume_documents set updated_at=now()-interval '2 hours' where id=(current_setting('test.interrupted')::jsonb->>'documentId')::uuid;
select pg_temp.ok('stale upload claimed for cleanup',(select count(*)=1 from public.claim_resume_cleanup(pg_temp.id('owner'),pg_temp.id('company'))));
select public.finish_resume_cleanup(pg_temp.id('company'),(current_setting('test.interrupted')::jsonb->>'documentId')::uuid);
select pg_temp.ok('retry after cleanup reuses candidate',public.reserve_resume(pg_temp.id('owner'),pg_temp.id('company'),pg_temp.id('batch2'),1,repeat('c',64),'retry.pdf','application/pdf',10,1)->>'candidateId'=current_setting('test.interrupted')::jsonb->>'candidateId');
select pg_temp.ok('retry after cleanup has new operation token',(select operation_token<>(current_setting('test.interrupted')::jsonb->>'token')::uuid from public.resume_documents where id=(current_setting('test.interrupted')::jsonb->>'documentId')::uuid));
delete from public.company_members where user_id=pg_temp.id('owner');
select pg_temp.denied('membership revoked before commit blocks completion',$q$select public.finish_resume_upload(pg_temp.id('owner'),pg_temp.id('company'),(current_setting('test.interrupted')::jsonb->>'documentId')::uuid,(current_setting('test.interrupted')::jsonb->>'token')::uuid)$q$);
reset role;
select json_build_object('passed',count(*),'failed',0,'tests',json_agg(name)) as results from results;
rollback;
